\header { tagline = ##f }
\paper { paper-height = 380\mm system-separator-markup = \slashSeparator
  system-system-spacing.basic-distance = #15
}
\layout { indent = 0 \set Score.tempoHideNote = ##t \context { \Score \remove "Bar_number_engraver" } }
global = { \key g \minor \time 3/4 }

soprano = \relative c'' { \global \autoBeamOff
  \set Staff.midiPanPosition = -0.5 \set midiInstrument = "vibraphone"
  bes4 a8 bes g4 \repeat volta 2 { \repeat unfold 15 { bes4 a8 bes g4 | }
  \repeat unfold 4 { d'4 c8 d bes4 | }
  g'4 g8 g f ([es]) | d4 d8 d c ([bes]) | c4 c8 c d ([c]) | g4 g8 g g4 |
  d8 ([e fis g a bes]) | c ([d]) c4 bes |
  d,8 ([e fis g a bes]) | c ([d]) c4 bes |
  \repeat unfold 4 { bes4 a8 bes g4 | } }
  \alternative { { bes4 a8 bes g4 } { g2.~ | g2.~ | g2. |
    \tempo 4. = 72 d'4 c8 d \tempo 4. = 36 g,4 } } \bar "|."
}

alto = \relative c' { \global \autoBeamOff
  \set Staff.midiPanPosition = -0.5 \set midiInstrument = "oboe"
  R2. | \repeat volta 2 { R2.*3 | \repeat unfold 2 { g'2. | f | es | d | }
  \repeat unfold 4 { g4 g8 g g4 | }
  \repeat unfold 4 { bes4 a8 bes g4 | }
  \repeat unfold 4 { g4 g8 g g4 | }
  d2. | e4 fis g | d2. | e4 fis g |
  d2.( | c | f | es | }
  \alternative { { d2) r4 } { d2.~ | d~ | d | bes'4 a8 bes g4 } } \bar "|."
}

tenor = \relative c' { \global \autoBeamOff
  \set Staff.midiPanPosition = -0.5 \set midiInstrument = "french horn"
  R2. | \repeat volta 2 { \repeat unfold 7 { R2. } es2. | bes | c | g |
  c4 c8 c c4 | d4 d8 d d4 | es4 es8 es es4 | d4 d8 d d4 |
  d2. | e | f4 (es) d | g8 ([f]) es4 d |
  d4 es8 es d ([c]) | d4 d8 d d4 | es es8 es f ([es]) | d4 d8 d d4 |
  \repeat unfold 4 { bes4 a8 bes g4 | }
  g2.~ | g~ | g~ | g~ | }
  \alternative { { g2 r4 } { \repeat unfold 3 { bes4 a8 bes g4 } R2. } } \bar "|."
}

bass = \relative c { \global \autoBeamOff
  \set Staff.midiPanPosition = -0.5 \set midiInstrument = "tuba"
  R2. | \repeat volta 2 { \repeat unfold 11 { R2. }
  es4 es8 es es4 | g g8 g g4 | c c8 c c4 | g g8 g g4 |
  \repeat unfold 4 { g g8 g g4 | }
  \repeat unfold 4 { bes a8 bes g4 | }
  d2. | d | d~ | d2 es4 |
  f2.( | es | d | c | }
  \alternative { { g2) r4 } { g2.~ | g~ |g | R2. } } \bar "|."
}

sopranoVerse = \lyricmode {
  Щед -- рик, щед -- рик, щед -- рі -- воч -- ка,
  При -- ле -- ті -- ла лас -- ті -- воч -- ка,
  Ста -- ла со -- бі ще -- бе -- та -- ти,
  Гос -- по -- да -- ря ви -- кли -- ка -- ти.
  Вий -- ди, вий -- ди, гос -- по -- да -- рю,
  По --ди -- ви --ся на ко -- ша -- ру.
  Там о -- веч -- ки по -- ко -- ти -- лись,
  a яг -- нич -- ки на -- ро -- ди -- лись.
  В~те -- бе то -- вар весь хо -- ро -- ший,
  Бу -- деш ма -- ти мір -- ку гро -- шей,
  В~те -- бе то -- вар весь хо -- ро -- ший,
  Бу -- деш ма -- ти мір -- ку гро -- шей,
  В~те -- бе жін -- ка чор -- но -- бро -- ва.
  Хоч не гро -- ші, то по -- ло -- ва,
  В~те -- бе жін -- ка чор -- но -- бро -- ва.
  Щед -- рик, щед -- рик
  M __ лас -- ті -- воч -- ка.
}

altoVerse = \lyricmode {
  Ста -- ла со -- бі ще -- бе -- та -- ти,
  \repeat unfold 55 { \skip 1 } M __
}

tenorVerse = \lyricmode {
  \repeat unfold 20 { \skip 1 } В~те -- бе то -- вар хо -- ро -- ший,
  \repeat unfold 16 { \skip 1 } Хоч не гро -- ші, то по -- ло -- ва,
  В~те -- бе жін -- ка чор -- но -- бро -- ва.
  \skip 1 Щед -- рик, щед -- рик,
  щед -- рі -- воч -- ка, При -- ле -- ті -- ла.
}

bassVerse = \lyricmode {
  \repeat unfold 48 { \skip 1 } В~те -- бе жін -- ка
}

\score {
  \new ChoirStaff <<
    \new Staff = "sa"
    <<
      \new Voice = "soprano" { \voiceOne \soprano }
      \new Voice = "alto" { \voiceTwo \alto }
    >>
    \new Lyrics \with {
      alignAboveContext = "sa" \override VerticalAxisGroup #'staff-affinity = #DOWN }
    \lyricsto "soprano" \sopranoVerse
    \new Lyrics \lyricsto "alto" \altoVerse
    \new Staff = "tb" \with { \consists "Merge_rests_engraver" }
    <<
      \clef bass
      \new Voice = "tenor" { \voiceOne \tenor }
      \new Voice = "bass" { \voiceTwo \bass }
    >>
    \new Lyrics \with {
      alignAboveContext = "tb" \override VerticalAxisGroup #'staff-affinity = #DOWN }
    \lyricsto "tenor" \tenorVerse
    \new Lyrics \lyricsto "bass" \bassVerse
  >>
  \layout { }
}
\score { \unfoldRepeats { << \soprano \\ \alto \\ \tenor \\ \bass >> }
  \midi {
    \tempo 4.=112
    \context { \Score midiChannelMapping = #'instrument }
    \context { \Staff \remove "Staff_performer" }
    \context { \Voice \consists "Staff_performer" }
  }
}
</score>

== In popular culture ==
Originally a New Year celebration song, "{{lang|uk-Latn|Shchedryk}}" is not a popular Christmas song in Ukraine, unlike elsewhere in the world where the introduction of the Wilhousky lyrics became popularized since the late 1930s. Instead, in Ukraine its association with the new year is retained and the song is more often performed on the eve of the Julian Calendar new year.<ref name="Alm" />

It was used in the [[Lost media|lost]] 1930 [[Cinema of the United States|American film]] "[[Song of the Flame (film)|Song of the Flame]]", which takes place during the [[Russian Revolution]]. The song is played during a scene in a [[harvest festival]], and sung by a choir.<ref>{{Cite AV media |url=https://www.youtube.com/watch?v=Hl1uJUoHxBw |title=The Song Of The Flame 1930 (Reels 1,4,5,7, & 9, Audio Only) |date=2016-08-20 |last=The Vitaphone Sound-On-Disc Channel |access-date=2026-07-10 |via=YouTube}}</ref>

The ''Family Guy'' episode "[[Deep Throats]]" contains a scene where Peter Griffin sings a song to the same tune as "{{lang|uk-Latn|Shchedryk}}" while performing a part-time job.

"{{lang|uk-Latn|Shchedryk}}" was [[cover version|covered]] by [[Ukrainian rock]] band {{langrlink|uk-Latn|Vopli Vidopliassova}} in 2012.

"{{lang|uk-Latn|Shchedryk}}" was used in the 2016 film ''[[Hunt for the Wilderpeople]]'', and in the 2024 horror film ''[[Immaculate_(2024_film)|Immaculate]]'', just as Sister Cecilia gives birth.{{cn|date=December 2024}} In the Christmas scene of the 2022 Ukrainian historical drama film ''[[Carol of the Bells (film)|Carol of the Bells]]'', children are caroling and singing "{{lang|uk-Latn|Shchedryk}}". The role of the song in the film is as a symbol of peace, hope, and faith for a better future.<ref name="Uni1">{{cite web |title=сторична драма "Щедрик": чому її варто подивитися кожному українцю |url=https://www.unian.ua/lite/kino/istorichna-drama-shchedrik-chomu-jiji-varto-podivitisya-kozhnomu-ukrajincyu-12067887.html |publisher=Unian |access-date=10 March 2024 |ref=|trans-title=Historical drama "Shchedryk": why every Ukrainian should watch it |language=uk |date=5 December 2022}}</ref>

Because of the [[Russian invasion of Ukraine]], at the second semifinal of the [[Eurovision Song Contest 2023]] that was held in the UK city of [[Liverpool]] rather than in Ukraine, the song was sung by the Ukrainian singers {{langrlink|uk-Latn|Zlata Dziunka}} and {{langrlink|uk-Latn|Mariya Yaremchuk}}.<ref name="Byl">{{cite news |last1=Bylim |first1=Olena |title="A Cherry Orchard Near the House" and "Shchedryk": Maria Yaremchuk, OTOY, Zlata Dziunka "blew up" Eurovision with their Ukrainian performances (video) |url=https://news-eng.uaportal.com/section-news/news-sadok-vishnevij-kolo-hati-i-schedrik-mariya-yaremchuk-otoy-zlata-dzyunka-vzorvali-evrovidenie-svoim-ukrainskim-vyistupleniem-video-12-05-2023.html |access-date=24 December 2024 |work=UAportal|date=12 May 2023}}</ref>

